//! Bounded 52B420 ordered merge of supplied records; factors are caller inputs.
//! No topology, active smoothing policy, live identity or final skin established.
use std::{env,fs,io::{self,Write}};use spore_core::native_sse::{self,Policy,SseError};
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),2);let b=fs::read(&a[1]).unwrap();assert_eq!(b.len(),880);let cases=[[(0,0.5f32),(1,1.0)],[(1,1.0),(0,0.5)],[(3,0.0),(3,1.0)],[(12,1.0),(22,0.25)]];let mut out=Vec::new();native_sse::scoped(Policy::Mxcsr1f80,||{for case in cases{let mut entries:Vec<(u8,f32)>=Vec::new();for (i,factor) in case {let r=&b[i*20..i*20+20];for j in 0..4{let w=f32::from_le_bytes(r[4+j*4..8+j*4].try_into().unwrap());assert!(w.is_finite());if w<=0.0{break}let mut v=w;unsafe{std::arch::asm!("mulss {v}, {factor}",v=inout(xmm_reg)v,factor=in(xmm_reg)factor,options(nostack,preserves_flags));}if let Some((_,old))=entries.iter_mut().find(|e|e.0==r[j]){unsafe{std::arch::asm!("addss {v}, {old}",v=inout(xmm_reg)v,old=in(xmm_reg)*old,options(nostack,preserves_flags));}*old=v}else{entries.push((r[j],v))}}}assert!(entries.len()<=8);out.extend((entries.len() as u32).to_le_bytes());for (id,v) in &entries{out.extend([*id,0,0,0]);out.extend(v.to_bits().to_le_bytes())}out.resize(out.len()+(8-entries.len())*8,0);}Ok::<(),SseError>(())}).unwrap();io::stdout().write_all(&out).unwrap()}
